'use strict';

// Match only DM notifications generated by the Borg management website.
// Deliberately do not treat every bot-authored DM as a website notification.
const WEBSITE_NOTIFICATION_FOOTERS = new Set([
  'إدارة البرج • مراجعة التسليمات',
  'إدارة البرج • طلبات الإجازة',
  'إدارة البرج • الطلبات الإدارية',
  'إدارة البرج • إعادة المهمات',
  'إدارة البرج • تذكير مواعيد التسليم',
]);

const LEGACY_WEBSITE_NOTIFICATION_TITLES = new Set([
  '✅ تم قبول تسليم المهمة',
  '❌ تم رفض تسليم المهمة',
]);

function isWebsiteNotificationMessage(message) {
  const content = String(message?.content || '');
  if (content.includes('رسالة جديدة في شات الاستاف بالموقع')) return true;

  const embeds = Array.isArray(message?.embeds) ? message.embeds : [];
  for (const item of embeds) {
    // Supports both plain Discord REST payloads and discord.js Embed instances.
    const data = item?.data || item || {};
    const title = String(item?.title || data?.title || '');
    const footer = String(item?.footer?.text || data?.footer?.text || '');
    if (WEBSITE_NOTIFICATION_FOOTERS.has(footer)) return true;
    // The worker's previous task-review DM had no footer. Match its exact old titles
    // so historical site notifications can still be removed without deleting other DMs.
    if (LEGACY_WEBSITE_NOTIFICATION_TITLES.has(title)) return true;
  }
  return false;
}

module.exports = { isWebsiteNotificationMessage };
